type ButtonProps = React.ButtonHTMLAttributes<HTMLButtonElement> & { tone?: "primary" | "secondary" | "ghost" | "outline" };
export function Button({ tone = "primary", className = "", ...props }: ButtonProps) {
  const tones = { primary: "bg-primary text-primary-foreground hover:brightness-95", secondary: "bg-secondary text-secondary-foreground hover:brightness-110", ghost: "bg-transparent text-muted-foreground hover:bg-muted", outline: "border bg-card text-foreground hover:bg-muted" };
  return <button className={`inline-flex min-h-9 items-center justify-center gap-2 rounded-md px-4 text-sm font-bold transition disabled:pointer-events-none disabled:opacity-50 ${tones[tone]} ${className}`} {...props} />;
}

