export function AppShell({ title, subtitle, children, actions }: { title: string; subtitle?: string; children: ReactNode; actions?: ReactNode }) {
  const location = useLocation();
  const [open, setOpen] = useState(false);
  const { session, name } = useRequireSession();
  const navigate = useNavigate();
  const initials = name.split(/[\s@.]+/).filter(Boolean).slice(0,2).map(w=>w[0]!.toUpperCase()).join("");
  if (!session) return <div className="grid min-h-screen place-items-center bg-background text-sm text-muted-foreground">Verificando sesión…</div>;
  return <div className="min-h-screen bg-background lg:flex">
    <aside className={`fixed inset-y-0 left-0 z-40 flex w-64 flex-col bg-sidebar text-sidebar-foreground transition-transform lg:translate-x-0 ${open ? "translate-x-0" : "-translate-x-full"}`}>
      <div className="flex h-20 items-center justify-between border-b border-white/10 px-5">
        <Link to="/panel" className="flex items-center gap-3 text-white"><span className="grid size-9 place-items-center rounded-md bg-primary font-extrabold">S</span><span><b className="text-xl">SAGE-UPE</b><small className="block text-[9px] font-semibold text-sidebar-foreground">ÁREA DE SEGUIMIENTO DOCUMENTAL</small></span></Link>
        <button aria-label="Cerrar menú" onClick={() => setOpen(false)} className="lg:hidden"><X className="size-5" /></button>
      </div>
      <div className="mx-4 mt-5 flex items-center gap-2 rounded-md bg-sidebar-muted px-3 py-2 text-[11px] font-semibold"><ShieldCheck className="size-4 text-primary" /> Sesión Segura Encriptada</div>
      <nav className="mt-5 space-y-1 px-3">{nav.map(([to, label, Icon, count]) => <Link key={to} to={to} onClick={() => setOpen(false)} className={`flex min-h-11 items-center gap-3 rounded-md border-l-2 px-3 text-sm transition ${location.pathname === to ? "border-primary bg-sidebar-muted text-white" : "border-transparent hover:bg-sidebar-muted"}`}><Icon className={`size-5 ${location.pathname === to ? "text-primary" : ""}`} /><span className="flex-1">{label}</span>{count && <span className="rounded-full bg-white/10 px-2 py-0.5 text-[10px] font-bold text-white">{count}</span>}</Link>)}</nav>
      <div className="mt-auto p-4"><div className="rounded-md bg-sidebar-muted p-3 text-[10px] leading-relaxed"><b className="text-warning">USO RESTRINGIDO</b><p className="mt-1">Acceso exclusivo para personal autorizado de la Unidad de Protección Especial. L.O.P.N.N.A. vigente.</p></div><div className="mt-4 flex items-center gap-3 border-t border-white/10 pt-4"><span className="grid size-9 shrink-0 place-items-center rounded-full bg-primary text-xs font-bold text-white">{initials}</span><span className="min-w-0 flex-1"><b className="block truncate text-xs text-white">{name}</b><button onClick={async()=>{await supabase.auth.signOut();navigate({to:"/"})}} className="text-[10px] underline">Cerrar sesión</button></span></div></div>
    </aside>
    {open && <button aria-label="Cerrar menú" className="fixed inset-0 z-30 bg-foreground/45 lg:hidden" onClick={() => setOpen(false)} />}
    <div className="min-w-0 flex-1 lg:ml-64"><header className="sticky top-0 z-20 flex min-h-20 items-center gap-4 border-b bg-card px-4 sm:px-7"><button aria-label="Abrir menú" onClick={() => setOpen(true)} className="grid size-10 place-items-center rounded-md border lg:hidden"><Menu /></button><div className="min-w-0 flex-1"><h1 className="truncate text-xl font-extrabold sm:text-2xl">{title}</h1>{subtitle && <p className="mt-1 truncate text-xs text-muted-foreground">{subtitle}</p>}</div><div className="hidden items-center gap-3 sm:flex">{actions ?? <><span className="rounded-md bg-accent px-3 py-2 text-xs font-bold text-accent-foreground">● UPE Activa - Distrito Metropolitano</span><button aria-label="Notificaciones" className="relative grid size-10 place-items-center rounded-full border"><Bell className="size-5"/><i className="absolute right-1 top-0 size-2 rounded-full bg-danger"/></button></>}</div></header><main className="p-4 sm:p-7">{children}</main></div>
  </div>;
}

export function Card({ children, className = "" }: { children: ReactNode; className?: string }) { return <section className={`min-w-0 overflow-hidden rounded-lg border bg-card shadow-sm ${className}`}>{children}</section>; }
export function SectionHead({ title, sub, action }: { title: string; sub?: string; action?: ReactNode }) { return <div className="flex items-start justify-between gap-3 border-b px-5 py-4"><div><h2 className="text-sm font-extrabold">{title}</h2>{sub && <p className="mt-1 text-xs text-muted-foreground">{sub}</p>}</div>{action}</div>; }
export function Badge({ children, kind="success" }: { children: ReactNode; kind?: "success"|"warning"|"danger"|"info"|"muted" }) { const cls={success:"bg-success-soft text-success",warning:"bg-warning-soft text-warning",danger:"bg-danger-soft text-danger",info:"bg-blue-50 text-secondary",muted:"bg-muted text-muted-foreground"};return <span className={`inline-flex rounded px-2 py-1 text-[10px] font-extrabold ${cls[kind]}`}>{children}</span>; }
export const formatCaseNumber=(s:string)=>{const d=s.replace(/\D/g,"").slice(0,8);return d.length>4?`${d.slice(0,4)}-${d.slice(4)}`:d;};
export function SearchBar({ onSearch, onChange, initial="" }: { onSearch?: (v:string) => void; onChange?: (v:string)=>void; initial?: string }) { const [value,setValue]=useState(initial); return <form onSubmit={e=>{e.preventDefault();onSearch?.(value)}} className="flex flex-col gap-2 sm:flex-row"><label className="flex min-h-11 flex-1 items-center gap-3 rounded-md border bg-input px-4"><Search className="size-5 text-muted-foreground"/><input aria-label="Número de expediente" inputMode="numeric" value={value} onChange={e=>{const v=formatCaseNumber(e.target.value);setValue(v);onChange?.(v)}} placeholder="N.° de expediente. Ej: 2021-0009" className="w-full bg-transparent text-sm outline-none placeholder:text-muted-foreground"/></label><Button type="submit" tone="secondary"><Search className="size-4"/>Buscar</Button></form>; }

