const familyNames: Record<string,string> = { "2021-0075": "Familia Corcino Marquez", "2021-0084": "Familia Duran Milla" };
export type Member = { name: string; id?: string; dni?: string; age?: string; birth?: string };
export type Family = { fid: string; code: string; year: string; team: Team; label: string; members: Member[]; state: string; stateKind: "success"|"warning"|"muted"; recs: NNACase[]; archived?: { autor: string; created_at: string }; isCopy?: boolean };
export const famId = (code: string, team: Team) => `${code}|${team}`;
export const recFid = (r: NNACase) => r.fid ?? famId(r.code, r.team);
const demoFamilies: Family[] = ([
    ["2022-0031","RIESGO","Luis Alberto Quispe","Activo","success"],
    ["2023-4402","DESPROTECCIÓN","Rodrigo Flores Díaz","Activo","success"],
    ["2024-1182","DESPROTECCIÓN","Juan Alberto Pérez","Activo","success"],
    ["2024-1182","RIESGO","José Antonio Prado","Activo","success"],
    ["2024-0941","RIESGO","María Elena Sánchez","Activo","success"],
    ["2024-1204","RIESGO","Ana Gabriela Luna","En revisión","warning"],
    ["2024-0511","DESPROTECCIÓN","Sofía Mariana Gómez","Activo","success"],
    ["2025-0012","DESPROTECCIÓN","Carla Vega Ríos","Activo","success"],
    ["2026-0004","RIESGO","Diego Huamán Soto","En revisión","warning"],
  ] as [string, Team, string, string, "success"|"warning"][]).map(([code,team,name,state,kind]) => ({ fid: famId(code,team), code, year: code.slice(0,4), team, label: "Grupo familiar (demostración)", members: [{ name }], state, stateKind: kind, recs: [] }));
function buildFamilies(recs: NNACase[], hidden: Set<string>): Family[] {
  const out: Family[] = [];
  for (const r of recs) {
    if (hidden.has(r.id)) continue;
    const fid = recFid(r);
    let f = out.find(x => x.fid === fid);
    if (!f) { f = { fid, code: r.code, year: r.code.slice(0,4), team: r.team, label: r.label ?? familyNames[r.code] ?? "Grupo familiar", members: [], state: "Activo", stateKind: "success", recs: [], isCopy: fid.includes("|copia-") }; out.push(f); }
    f.members.push({ name: r.nna, id: r.id, dni: r.dni, age: ageText(r.birth) || r.age, birth: r.birth }); f.recs.push(r);
  }
  return [...out, ...demoFamilies].sort((a,b)=>b.code.localeCompare(a.code));
}
export const YEARS = ["2021","2022","2023","2024","2025","2026"];
const OV_KEY = "sage-team-transfers";
let overrides: Record<string, Team> = {};
type Store = { extra: NNACase[]; hidden: Set<string>; archived: Record<string, { autor: string; created_at: string }> };
let store: Store = { extra: [], hidden: new Set(), archived: {} };
let storeLoaded = false;
const listeners = new Set<() => void>();
const emit = () => listeners.forEach(l => l());
export async function refreshStore() {
  const [r, h, a] = await Promise.all([
    supabase.from("registros_nna").select("*").order("created_at"),
    supabase.from("nna_registros").select("caso_base").eq("eliminado", true),
    supabase.from("expedientes_archivo").select("*"),
  ]);
  store = {
    extra: (r.data ?? []).map(x => ({ ...(x.data as unknown as NNACase), id: x.id, fid: x.fid, code: x.code, team: x.team as Team, label: x.label })),
    hidden: new Set((h.data ?? []).map(x => x.caso_base).filter(Boolean) as string[]),
    archived: Object.fromEntries((a.data ?? []).map(x => [x.fid, { autor: x.autor, created_at: x.created_at }])),
  };
  storeLoaded = true; emit();
}
export function transferTeam(fid: string, team: Team) { overrides = { ...overrides, [fid]: team }; try { localStorage.setItem(OV_KEY, JSON.stringify(overrides)); } catch { /* ignore */ } emit(); }
function useStoreTick() {
  const [, setTick] = useState(0);
  useEffect(() => { try { overrides = JSON.parse(localStorage.getItem(OV_KEY) || "{}"); } catch { overrides = {}; } const l = () => setTick(t => t + 1); listeners.add(l); l(); if (!storeLoaded) refreshStore(); return () => { listeners.delete(l); }; }, []);
  return store;
}
export function useAllRecords(): NNACase[] { const st = useStoreTick(); return useMemo(() => [...caseRecords, ...st.extra], [st]); }
export function useFamilies(): Family[] {
  const st = useStoreTick();
  const ov = overrides;
  return useMemo(() => buildFamilies([...caseRecords, ...st.extra], st.hidden).map(f => { const arch = st.archived[f.fid]; return { ...f, team: ov[f.fid] ?? f.team, ...(arch ? { archived: arch, state: "Archivado", stateKind: "muted" as const } : {}) }; }), [st, ov]);
}

export async function archiveFamily(fid: string) {
  const { data } = await supabase.auth.getUser();
  const { data: p } = data.user ? await supabase.from("profiles").select("full_name").eq("id", data.user.id).maybeSingle() : { data: null };
  const { error } = await supabase.from("expedientes_archivo").insert({ fid, autor: p?.full_name || data.user?.email || "" });
  if (error) alert("No se pudo archivar: " + error.message);
  await refreshStore();
}
function TransferMenu({ fam }: { fam: Family }) {
  const admin = useIsAdmin();
  const [open, setOpen] = useState(false); const [confirm, setConfirm] = useState(false); const [done, setDone] = useState(""); const [arch, setArch] = useState(false);
  const target: Team = fam.team === "RIESGO" ? "DESPROTECCIÓN" : "RIESGO";
  return <div className="relative">
    <Button type="button" tone="outline" className="px-3" aria-label="Más opciones del expediente" onClick={() => setOpen(o => !o)}><MoreHorizontal className="size-4"/></Button>
    {open && <><button type="button" aria-label="Cerrar opciones" className="fixed inset-0 z-10 cursor-default" onClick={() => setOpen(false)}/><div className="absolute right-0 z-20 mt-1 w-64 rounded-md border bg-card p-1 shadow-lg"><button type="button" onClick={() => { setOpen(false); setConfirm(true); }} className="flex w-full items-center gap-2 rounded px-3 py-2 text-left text-xs font-bold hover:bg-muted"><ArrowLeftRight className="size-4"/>Transferir a {target}</button>{admin && <button type="button" onClick={() => { setOpen(false); setArch(true); }} className="flex w-full items-center gap-2 rounded px-3 py-2 text-left text-xs font-bold text-danger hover:bg-muted"><Archive className="size-4"/>Archivar expediente</button>}</div></>}
    {arch && <div role="dialog" aria-modal="true" className="fixed inset-0 z-50 grid place-items-center bg-foreground/45 p-4"><div className="w-full max-w-md rounded-lg border bg-card p-6 text-left shadow-xl"><h2 className="text-base font-extrabold">¿Archivar el expediente {fam.code}?</h2><p className="mt-2 text-sm text-muted-foreground">Pasará a estado <b>Archivado</b>: dejará de aparecer entre los activos y no podrá modificarse. Toda su información se conserva para consulta.</p><div className="mt-5 flex justify-end gap-2"><Button type="button" tone="outline" onClick={() => setArch(false)}>Cancelar</Button><Button type="button" className="bg-danger" onClick={async () => { await archiveFamily(fam.fid); setArch(false); }}>Sí, archivar</Button></div></div></div>}
    {confirm && <div role="dialog" aria-modal="true" className="fixed inset-0 z-50 grid place-items-center bg-foreground/45 p-4"><div className="w-full max-w-md rounded-lg border bg-card p-6 text-left shadow-xl"><h2 className="text-base font-extrabold">¿Transferir el expediente {fam.code}?</h2><p className="mt-2 text-sm text-muted-foreground">El expediente pasará de <b>{fam.team}</b> a <b>{target}</b>. El cambio aplica a los {fam.members.length} NNA del grupo familiar.</p><div className="mt-5 flex justify-end gap-2"><Button type="button" tone="outline" onClick={() => setConfirm(false)}>Cancelar</Button><Button type="button" onClick={() => { transferTeam(fam.fid, target); setConfirm(false); setDone(`Expediente transferido a ${target}.`); }}>Sí, transferir</Button></div></div></div>}
    {done && <div role="status" className="absolute right-0 top-full z-20 mt-1 w-56 rounded-md bg-success-soft p-2 text-xs font-bold text-success">{done}</div>}
  </div>;
}

function DataTable({ children }: { children: ReactNode }) { return <div className="overflow-x-auto"><table className="w-full min-w-[680px] border-collapse text-left text-xs">{children}</table></div>; }
const Th=({children}:{children:ReactNode})=><th className="bg-muted px-4 py-3 text-[10px] font-extrabold uppercase text-muted-foreground">{children}</th>;
const Td=({children,className=""}:{children:ReactNode;className?:string})=><td className={`border-t px-4 py-3 ${className}`}>{children}</td>;

export function DashboardPage() { const navigate=useNavigate(); const stats=[["EXPEDIENTES ACTIVOS","142","+12 nuevos",Folder,"success"],["PENDIENTES SEGUIMIENTO","12","4 urgentes",Clock3,"warning"],["ACTUACIONES HOY","8","Promedio diario",FilePlus2,"info"],["DOCUMENTOS RECIBIDOS","24","100% procesado",Download,"success"],["ALERTAS CRÍTICAS","4","Atención legal",AlertCircle,"danger"]] as const; return <AppShell title="Panel de Control Operativo" subtitle="SAGE-UPE - Área de Seguimiento Documental"><Card className="p-5"><h2 className="font-extrabold">Buscador de Expediente</h2><p className="mb-4 mt-1 text-xs text-muted-foreground">Búsqueda únicamente por número de expediente (formato 2021-0009).</p><SearchBar onSearch={v=>navigate({to:"/buscar",search:{q:v||undefined}})}/><div className="mt-3 flex flex-wrap items-center gap-2 text-[10px] text-muted-foreground">Búsquedas frecuentes: <Badge kind="muted">Expedientes activos</Badge><Badge kind="muted">Pendientes</Badge><Badge kind="muted">Documentos recibidos</Badge></div></Card><div className="my-5 grid grid-cols-2 gap-3 lg:grid-cols-5">{stats.map(([label,note,tag,Icon,kind])=><Card key={label} className="p-4"><div className="flex justify-between gap-2"><span className="truncate text-[10px] font-extrabold text-muted-foreground">{label}</span><span className="grid size-8 place-items-center rounded-md bg-muted"><Icon className="size-4"/></span></div><strong className="mt-4 block text-3xl">{note}</strong><div className="mt-2 flex items-center gap-2"><Badge kind={kind}>{tag}</Badge><small className="text-muted-foreground">últimos 7 días</small></div></Card>)}</div><div className="grid gap-5 xl:grid-cols-[minmax(0,2fr)_minmax(260px,0.9fr)]"><Card><SectionHead title="Seguimiento Prioritario de Medidas de Protección" sub="Expedientes ordenados por prioridad y tiempo activo." action={<Button tone="outline" className="px-3"><SlidersHorizontal className="size-4"/>Filtrar</Button>}/><DataTable><thead><tr><Th>Código único</Th><Th>NNA</Th><Th>Equipo</Th><Th>Etapa</Th><Th>Tiempo activo</Th><Th>Prioridad</Th><Th>Especialista</Th></tr></thead><tbody>{cases.map((r,i)=><tr key={r[0]} className="hover:bg-muted/60"><Td><Link to="/expediente" search={{caso:undefined}} className="font-extrabold text-secondary">{r[0]}</Link></Td><Td>{r[1]}</Td><Td><TeamBadge team={r[6]}/></Td><Td>{r[2]}</Td><Td className={i===0||i>2?"font-bold text-danger":""}>{r[3]}</Td><Td><Badge kind={r[4]==="Alta"?"danger":r[4]==="Media"?"warning":"success"}>{r[4]}</Badge></Td><Td>{r[5]}</Td></tr>)}</tbody></DataTable><div className="flex justify-between border-t bg-muted/50 px-5 py-3 text-xs text-muted-foreground"><span>Mostrando 5 de 142 expedientes activos</span><Link to="/buscar" search={{q:undefined}} className="font-bold text-secondary">Ver todos →</Link></div></Card><Alerts /></div><BirthdaysPanel people={birthdayPeople}/></AppShell>; }

function Alerts(){const list=[["ALERTA DE SEGUIMIENTO","Hace 10m","Expediente 2024-1182 requiere validación documental antes de cerrar la actuación.","danger"],["PENDIENTE DE REVISIÓN","Hace 1 hora","Expediente 2024-0941 permanece sin actualización del seguimiento.","warning"],["DOCUMENTO PENDIENTE","Hace 3 horas","Falta incorporar el informe solicitado para 2024-1204.","warning"]] as const;return <Card><SectionHead title="Alertas" sub="Avisos relevantes para las actuaciones del día."/><div className="space-y-2 p-4">{list.map(([a,t,d,k])=><div key={a} className="rounded-md border bg-muted/50 p-3"><div className="flex justify-between gap-2"><b className={k==="danger"?"text-[10px] text-danger":"text-[10px] text-warning"}>{a}</b><small className="text-[9px] text-muted-foreground">{t}</small></div><p className="mt-1 text-xs leading-relaxed">{d}</p><small className="font-bold text-secondary">Ref: 2024-1182</small></div>)}</div></Card>}

export function SearchPage(){
  const { q: q0 } = useSearch({ strict: false }) as { q?: string };
  const families = useFamilies();
  const [q,setQ]=useState(q0 ?? "");
  const [team,setTeam]=useState<"TODOS"|Team>("TODOS");
  const [year,setYear]=useState<string>("TODOS");
  const [estado,setEstado]=useState<"ACTIVOS"|"ARCHIVADOS">("ACTIVOS");
  const byTeam=families.filter(f=>(team==="TODOS"||f.team===team)&&(estado==="ARCHIVADOS"?!!f.archived:!f.archived));
  const filtered=byTeam.filter(f=>(year==="TODOS"||f.year===year)&&(!q||f.code.startsWith(q)));
  const folder=(y:string,label:string,count:number)=><button type="button" key={y} onClick={()=>setYear(y)} className={`flex min-w-24 items-center gap-2 rounded-md border px-3 py-2 text-left text-xs font-bold transition ${year===y?"border-primary bg-accent text-accent-foreground":"bg-card hover:bg-muted"}`}><Folder className="size-4 shrink-0"/><span>{label}<small className="block text-[10px] font-semibold text-muted-foreground">{count} exp.</small></span></button>;
  return <AppShell title="Buscar expediente" subtitle="UPE Activa - Distrito Metropolitano"><Card className="p-5"><SearchBar initial={q0 ?? ""} onChange={setQ} onSearch={setQ}/><p className="mt-2 text-[10px] text-muted-foreground">La búsqueda se realiza únicamente por número de expediente (formato 2021-0009).</p>
    <div className="mt-4 flex flex-col gap-2 sm:flex-row sm:items-end"><label className="grid gap-1 text-xs font-bold"><span>Equipo / Categoría</span><select value={team} onChange={e=>setTeam(e.target.value as "TODOS"|Team)} className="min-h-11 rounded-md border bg-input px-3 py-2.5 text-sm"><option value="TODOS">Todos los equipos</option><option value="RIESGO">Riesgo</option><option value="DESPROTECCIÓN">Desprotección</option></select></label><label className="grid gap-1 text-xs font-bold"><span>Estado</span><select value={estado} onChange={e=>setEstado(e.target.value as "ACTIVOS"|"ARCHIVADOS")} className="min-h-11 rounded-md border bg-input px-3 py-2.5 text-sm"><option value="ACTIVOS">Expedientes activos</option><option value="ARCHIVADOS">Archivamiento (archivados)</option></select></label><p className="text-[10px] text-muted-foreground sm:pb-3">La numeración puede repetirse entre equipos; verifique siempre la categoría del expediente.</p></div>
    <div className="mt-4"><span className="text-xs font-bold">Carpetas por año</span><div className="mt-2 flex flex-wrap gap-2">{folder("TODOS","Todos",byTeam.length)}{YEARS.map(y=>folder(y,y,byTeam.filter(f=>f.year===y).length))}</div></div>
    <div className="mt-5"><DataTable><thead><tr><Th>N.° Expediente</Th><Th>Equipo</Th><Th>Año</Th><Th>Grupo familiar / NNA</Th><Th>Estado</Th><Th>Acción</Th></tr></thead><tbody>{filtered.length===0&&<tr><Td className="text-center text-muted-foreground"><span>No se encontraron expedientes con ese número.</span></Td></tr>}{filtered.map(f=><tr key={f.fid} className="align-top"><Td><Link to="/expediente" search={{caso:f.members[0]?.id}} className="font-extrabold text-secondary underline">{f.code}</Link></Td><Td><TeamBadge team={f.team}/></Td><Td>{f.year}</Td><Td><b className="block">{f.label}</b><span className="mt-1 flex flex-wrap gap-1">{f.members.map(m=>m.id?<Link key={m.name} to="/expediente" search={{caso:m.id}} className="rounded bg-muted px-2 py-0.5 text-[11px] hover:bg-accent">{m.name}</Link>:<span key={m.name} className="rounded bg-muted px-2 py-0.5 text-[11px]">{m.name}</span>)}</span>{f.members.length>1&&<small className="mt-1 block text-muted-foreground">{f.members.length} hermanos en este expediente</small>}</Td><Td><Badge kind={f.stateKind}>{f.state}</Badge></Td><Td><Link to="/expediente" search={{caso:f.members[0]?.id}} className="inline-flex items-center gap-1 font-bold text-secondary">Ver expediente <ChevronRight className="size-4"/></Link></Td></tr>)}</tbody></DataTable></div></Card><Link to="/panel" className="mt-5 inline-flex items-center gap-2 text-sm font-bold text-muted-foreground">← Volver</Link></AppShell>}

const Info=({title,children}:{title:string;children:ReactNode})=><Card><SectionHead title={title}/><div className="space-y-3 p-5 text-xs leading-relaxed">{children}</div></Card>;
const Row=({label,children}:{label:string;children:ReactNode})=><div className="grid grid-cols-[120px_1fr] gap-3"><b className="text-[10px] text-muted-foreground">{label}</b><span>{children}</span></div>;
const personName=(s:string)=>(s.split("—")[0]??s).trim();
export const birthdayPeople: Person[] = (()=>{ const out: Person[]=[]; const seen=new Set<string>();
  const add=(p:Person)=>{ const k=p.name+"|"+p.code; if(seen.has(k)||!parseDMY(p.birth))return; seen.add(k); out.push(p); };
  for(const r of caseRecords){ add({name:r.nna,role:"NNA",birth:r.birth,code:r.code,caso:r.id});
    const resp=personName(r.responsible.replace(/\(.*\)/,""));
    if(parseDMY(r.mother)) add({name:personName(r.mother),role:personName(r.mother)===resp?"Madre · Responsable":"Madre",birth:r.mother,code:r.code});
    if(parseDMY(r.father)) add({name:personName(r.father),role:personName(r.father)===resp?"Padre · Responsable":"Padre",birth:r.father,code:r.code}); }
  return out; })();
function RealCasePage({ rec }: { rec: NNACase }) {
  const fam = useFamilies().find(f => f.fid === recFid(rec));
  const base = fam?.recs ?? [rec];
  const team = fam?.team ?? rec.team;
  const archived = fam?.archived;
  const acts = usePtiActs(rec.id, rec.acts);
  const resolved = hasMajorityResolution(acts.items.map(a=>a.text));
  const age = ageText(rec.birth) || rec.age;
  const adult = parseInt(age) >= 18;
  return <AppShell title={rec.code} subtitle={`NNA: ${rec.nna} · SAGE-UPE Área de Seguimiento · Equipo de ${team === "RIESGO" ? "Riesgo" : "Desprotección"}`} actions={<><TeamBadge team={team}/>{archived?<Badge kind="muted">ARCHIVADO</Badge>:fam&&<TransferMenu fam={fam}/>}<Link to="/buscar" search={{q:undefined}}><Button tone="outline">Volver</Button></Link>{!archived&&<Link to="/nueva-actuacion"><Button>Nueva actuación</Button></Link>}</>}>
    {archived?<div className="mb-4 flex items-start gap-3 rounded-lg border-2 border-muted-foreground/40 bg-muted p-4"><Archive className="size-5 shrink-0"/><div className="text-xs"><b className="block text-sm">Expediente archivado</b><p className="mt-1 text-muted-foreground">Archivado el {new Date(archived.created_at).toLocaleDateString("es-PE")}{archived.autor?` por ${archived.autor}`:""}. Solo consulta: la información se conserva y no puede modificarse.</p></div></div>:<MajorityAlert casoId={rec.id} birth={rec.birth} name={rec.nna} resolved={resolved}/>}
    <div className="grid gap-4 xl:grid-cols-[minmax(0,2fr)_340px]"><div className="space-y-4">
      <div className="grid gap-4 md:grid-cols-2">
        <Info title="Datos del NNA"><Row label="Nombres completos"><span className="font-bold">{rec.nna}</span></Row><Row label="DNI">{rec.dni}</Row><Row label="Fecha Nacimiento">{rec.birth}</Row><Row label="Edad"><span className={adult?"font-extrabold text-danger":""}>{age}</span></Row><Row label="N.° Expediente"><b className="text-secondary">{rec.code}</b> <TeamBadge team={team}/></Row></Info>
        <Info title="Progenitores y Responsable"><Row label="Madre biológica">{withAges(rec.mother)}</Row><Row label="Padre biológico">{withAges(rec.father)}</Row><Row label="Responsable actual">{rec.responsible}</Row></Info>
      </div>
      <ContactsPanel ambito={recFid(rec)} readOnly={!!archived}/>
      <Info title="Situación y Antecedentes"><p>{rec.summary}</p></Info>
      <Info title="PTI (Plan de Trabajo Individual)"><b className="text-success">Objetivo General:</b><p>{rec.ptiGeneral}</p><b>Objetivos Específicos:</b><ol className="list-decimal space-y-2 pl-4">{rec.ptiSpecific.map((o,i)=><li key={i}>{o}</li>)}</ol></Info>
      <PtiActsPanel casoId={rec.id} acts={acts} readOnly={!!archived}/>
      <Info title="Documentos generados en Actuaciones"><SavedDocuments casoId={rec.id} code={rec.code} readOnly={!!archived}/></Info>
    </div>
    <div className="space-y-4">
      <SiblingsPanel currentId={rec.id} base={base}/>
      <Info title="Alertas"><div className="rounded-md bg-warning-soft p-3"><Badge kind="warning">VIVIENDA / SERVICIOS</Badge><p className="mt-2">{rec.code==="2021-0084"?"Vivienda rústica sin servicio de desagüe; el progenitor no cumple con la manutención.":"Vivienda rústica sin servicio de energía eléctrica desde el último reporte."}</p></div><div className="rounded-md bg-danger-soft p-3"><Badge kind="danger">SEGUIMIENTO PSICOSOCIAL</Badge><p className="mt-2">Mantener visitas psicosociales inopinadas según el PTI.</p></div></Info>
      <Info title="Línea de Tiempo del Expediente">{["Ingreso del caso (gestión 2021)","Evaluación integral y diagnóstico familiar","Aprobación del PTI","Seguimiento psicosocial continuo"].map(x=><p key={x} className="relative border-l-2 border-primary pb-3 pl-4 before:absolute before:-left-[5px] before:top-1 before:size-2 before:rounded-full before:bg-primary">{x}</p>)}</Info>
    </div></div>
  </AppShell>;
}
export function CasePage(){
  const { caso } = useSearch({ strict: false }) as { caso?: string };
  const all = useAllRecords();
  const rec = all.find(r=>r.id===caso);
  if(caso && !rec) return <AppShell title="Cargando expediente…"><p className="text-sm text-muted-foreground">Buscando el expediente…</p></AppShell>;
  if(rec) return <RealCasePage rec={rec}/>;
  return <DemoCasePage/>;
}
