export function PendingPage(){const [done,setDone]=useState<string[]>([]);return <AppShell title="Pendientes y Alertas del Área de Seguimiento" subtitle="SAGE-UPE - Gestión de tareas pendientes y alertas automáticas"><Card className="grid gap-3 p-4 md:grid-cols-4"><select className="rounded-md border bg-input p-3 text-xs"><option>Todos los especialistas</option></select><select className="rounded-md border bg-input p-3 text-xs"><option>Todas las actividades</option></select><select className="rounded-md border bg-input p-3 text-xs"><option>Todas las alertas</option></select><Button tone="secondary"><Search className="size-4"/>Filtrar</Button></Card><div className="my-5 grid grid-cols-2 gap-3 lg:grid-cols-4">{[["VENCIDAS","7","Requieren atención inmediata"],["PARA HOY","5","Actividades programadas hoy"],["PRÓXIMAS (7 DÍAS)","14","Próximos 7 días"],["COMPLETADAS HOY","3","Finalizadas hoy"]].map(([a,b,c])=><Card key={a} className="p-5"><b className="text-[10px] text-muted-foreground">{a}</b><strong className="mt-4 block text-3xl">{b}</strong><small className="text-muted-foreground">{c}</small></Card>)}</div><div className="grid gap-5 xl:grid-cols-[minmax(0,2.2fr)_340px]"><div className="space-y-4">{pendingGroups.map(g=><Card key={g.title}><div className={`border-b px-5 py-3 text-sm font-extrabold ${g.tone==="danger"?"bg-danger-soft text-danger":g.tone==="warning"?"bg-warning-soft text-warning":"bg-blue-50 text-secondary"}`}>{g.title}</div><DataTable><thead><tr><Th>Expediente</Th><Th>NNA</Th><Th>Actividad</Th><Th>Responsable</Th><Th>Fecha</Th><Th>Plazo</Th><Th>Acciones</Th></tr></thead><tbody>{g.rows.map(r=>{const rowId=r.join("-");return <tr key={rowId} className={done.includes(rowId)?"opacity-50":""}><Td className="font-bold text-secondary">{r.at(0)}</Td>{r.slice(1).map((x,i)=><Td key={`${i}-${x}`}>{x}</Td>)}<Td><div className="flex gap-1"><Link to="/nueva-actuacion"><Button className="px-2 text-[9px]">Registrar</Button></Link><Button tone="outline" className="px-2 text-[9px]" onClick={()=>setDone([...done,rowId])}>Completar</Button></div></Td></tr>})}</tbody></DataTable></Card>)}<Pager text="Mostrando 8 de 26 pendientes"/></div><Info title="Configuración de Alertas"><div className="rounded-md border p-3"><b>Alerta de vencimiento</b><p className="text-muted-foreground">Las actividades pasan a vencidas al día siguiente.</p></div><div className="rounded-md border p-3"><b>Alerta de seguimiento</b><p className="text-muted-foreground">Se genera al no registrar actuaciones en 30 días.</p></div><div className="rounded-md border p-3"><b>Alerta crítica</b><p className="text-muted-foreground">Se escala al supervisor después de 7 días.</p></div></Info></div></AppShell>}
