export function AdminPage(){const [tab,setTab]=useState<string>("Expedientes y hermanos");const rows=useMemo(()=>tab==="Configuración de Alertas"?[["Vencimiento","Alerta crítica","Diaria","08:00 AM","Responsable","Activa"],["Sin actuaciones","Alerta de seguimiento","Semanal","Lun 09:00 AM","Espec. + Superv.","Activa"],["Escalamiento","Actividad vencida","Diaria","07:00 AM","Superv. + Direct.","Activa"]]:[["Informe Social Inicial","Informe","15/08/2024","Activa"],["Evaluación Psicológica","Evaluación","20/07/2024","Activa"],["Resolución de Medida de Protección","Resolución","10/09/2024","Activa"],["Informe de Visita Domiciliaria","Informe","05/06/2024","Activa"]],[tab]);return <AppShell title="Panel de Administración del Sistema" subtitle="SAGE-UPE - Configuración y gestión del sistema"><div className="grid gap-5 xl:grid-cols-[400px_minmax(0,1fr)]"><div className="space-y-3">{adminSections.map(([label,note,Icon])=><button key={label} onClick={()=>setTab(label)} className={`flex w-full items-center gap-4 rounded-lg border bg-card p-4 text-left shadow-sm transition ${tab===label?"border-primary ring-2 ring-primary/20":"hover:bg-muted"}`}><span className="grid size-10 place-items-center rounded-md bg-muted"><Icon className="size-5 text-primary"/></span><span className="flex-1"><b className="block text-sm">{label}</b><small className="text-muted-foreground">Gestionar y configurar esta sección del sistema</small></span>{note&&<Badge>{note}</Badge>}</button>)}</div><Card className="self-start"><SectionHead title={`Gestión de ${tab}`} sub="Configuración de los recursos y parámetros del sistema." action={tab==="Expedientes y hermanos"?undefined:<Button>+ Agregar nuevo</Button>}/>{tab==="Expedientes y hermanos"?<AdminExpedientes/>:tab==="Usuarios y Permisos"?<div className="p-6"><div className="grid gap-3 md:grid-cols-2">{["Juan Pérez · Administrador","María Colmenares · Especialista","Lorena Mendoza · Especialista","Lucía Rojas · Psicóloga"].map(u=><div key={u} className="flex items-center gap-3 rounded-md border p-4"><span className="grid size-9 place-items-center rounded-full bg-accent"><UserRound className="size-4"/></span><b className="text-xs">{u}</b></div>)}</div></div>:<DataTable><thead><tr>{(tab==="Configuración de Alertas"?["Regla","Descripción","Frecuencia","Horario","Destinatarios","Estado"]:["Nombre","Tipo","Últ. modificación","Estado"]).map(x=><Th key={x}>{x}</Th>)}<Th>Acciones</Th></tr></thead><tbody>{rows.map((r,i)=><tr key={i}>{r.map((x,j)=><Td key={j} className={j===0?"font-bold":""}>{j===r.length-1?<Badge>{x}</Badge>:x}</Td>)}<Td><div className="flex gap-2"><Button tone="outline" className="px-2 text-[10px]">Editar</Button><Button tone="ghost" className="px-2 text-[10px] text-danger">Desactivar</Button></div></Td></tr>)}</tbody></DataTable>}</Card></div></AppShell>}

export function LoginPage(){const navigate=useNavigate();const [show,setShow]=useState(false);const [error,setError]=useState("");const [info,setInfo]=useState("");const [signup,setSignup]=useState(false);const [busy,setBusy]=useState(false);useEffect(()=>{supabase.auth.getSession().then(({data})=>{if(data.session)navigate({to:"/panel"})})},[navigate]);const submit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();setError("");setInfo("");const fd=new FormData(e.currentTarget);const email=String(fd.get("user")??"").trim();const password=String(fd.get("pass")??"");const full_name=String(fd.get("name")??"").trim();if(!/^\S+@\S+\.\S+$/.test(email)||password.length<6){setError("Ingrese un correo válido y una contraseña de al menos 6 caracteres.");return}if(signup&&!full_name){setError("Ingrese su nombre completo.");return}setBusy(true);if(signup){const {data,error}=await supabase.auth.signUp({email,password,options:{data:{full_name},emailRedirectTo:window.location.origin+"/panel"}});setBusy(false);if(error){setError(error.message);return}if(data.session){navigate({to:"/panel"});return}setInfo("Cuenta creada. Revise su correo para confirmarla y luego ingrese.");setSignup(false);return}const {error}=await supabase.auth.signInWithPassword({email,password});setBusy(false);if(error){setError(error.message.includes("Invalid")?"Correo o contraseña incorrectos.":error.message.includes("confirm")?"Debe confirmar su correo antes de ingresar.":error.message);return}navigate({to:"/panel"})};return <main className="relative grid min-h-screen place-items-center overflow-hidden bg-sidebar p-5"><div className="absolute left-0 top-0 size-96 -translate-x-1/3 -translate-y-1/3 rounded-full bg-primary/10 blur-3xl"/><div className="absolute bottom-0 right-0 size-96 translate-x-1/3 translate-y-1/3 rounded-full bg-primary/10 blur-3xl"/><div className="relative w-full max-w-md"><div className="mb-7 flex flex-col items-center text-white"><div className="flex items-center gap-3"><span className="grid size-11 place-items-center rounded-md bg-primary text-xl font-extrabold">S</span><h1 className="text-2xl font-extrabold">SAGE-UPE</h1></div><span className="mt-3 rounded bg-accent px-3 py-1 text-[10px] font-extrabold text-accent-foreground">ÁREA DE SEGUIMIENTO DOCUMENTAL</span></div><Card className="p-7"><h2 className="text-xl font-extrabold">Ingreso al Sistema</h2><p className="mt-2 text-xs leading-relaxed text-muted-foreground">Por favor, introduzca sus credenciales autorizadas de la Unidad de Protección Especial.</p><form onSubmit={submit} className="mt-6 space-y-4">{signup&&<Field label="Nombre completo"><input name="name" maxLength={80} placeholder="Ej: María Colmenares" className="w-full rounded-md border bg-input px-3 py-2.5 text-sm"/></Field>}<Field label="Correo institucional"><div className="relative"><UserRound className="absolute left-3 top-3 size-4 text-muted-foreground"/><input name="user" type="email" maxLength={120} autoComplete="username" placeholder="Ej: mcolmenares@upe.gob.pe" className="w-full rounded-md border bg-input py-2.5 pl-10 pr-3 text-sm outline-none focus:ring-2 focus:ring-primary"/></div></Field><Field label="Contraseña"><div className="relative"><LockKeyhole className="absolute left-3 top-3 size-4 text-muted-foreground"/><input name="pass" maxLength={100} type={show?"text":"password"} autoComplete="current-password" placeholder="••••••••••" className="w-full rounded-md border bg-input py-2.5 pl-10 pr-10 text-sm outline-none focus:ring-2 focus:ring-primary"/><button type="button" aria-label={show?"Ocultar contraseña":"Mostrar contraseña"} onClick={()=>setShow(!show)} className="absolute right-3 top-2.5 text-muted-foreground">{show?<EyeOff className="size-5"/>:<Eye className="size-5"/>}</button></div></Field>{error&&<p role="alert" className="text-xs font-bold text-danger">{error}</p>}{info&&<p role="status" className="text-xs font-bold text-success">{info}</p>}<Button className="w-full" type="submit" disabled={busy}>{busy?"Procesando…":signup?"Crear cuenta":"Iniciar sesión"}</Button><button type="button" onClick={()=>{setSignup(!signup);setError("")}} className="w-full text-center text-xs font-bold text-secondary underline">{signup?"Ya tengo cuenta: iniciar sesión":"¿Personal nuevo? Crear cuenta"}</button></form><div className="my-5 border-t"/><div className="flex items-center gap-2 rounded-md bg-sidebar p-3 text-[10px] font-bold text-white"><ShieldCheck className="size-4 text-primary"/>Sesión Segura Encriptada SSL</div></Card><div className="mt-5 rounded-md border-l-4 border-warning bg-sidebar-muted p-4 text-[10px] leading-relaxed text-sidebar-foreground"><b className="text-warning">USO ESTRICTAMENTE RESTRINGIDO</b><p className="mt-2">El acceso no autorizado está penalizado bajo la L.O.P.N.N.A. vigente. Todas las transacciones e ingresos son monitoreados y auditados.</p></div></div></main>}
function ActionLookup({onPick}:{onPick:(c:CaseData|null)=>void}){
  const families=useFamilies(); const [q,setQ]=useState(""); const [searched,setSearched]=useState(""); const [picked,setPicked]=useState("");
  const pick=(rec:NNACase|undefined,team:Team)=>{if(!rec){setPicked("");onPick(null);return}setPicked(rec.id);onPick({caso_id:rec.id,code:rec.code,team,nna:rec.nna,dni:rec.dni,birth:rec.birth,age:rec.age,mother:rec.mother,father:rec.father,responsible:rec.responsible,siblings:(families.find(f=>f.fid===recFid(rec))?.recs??[]).filter(r=>r.id!==rec.id).map(r=>r.nna).join(", "),ptiGeneral:rec.ptiGeneral});};
  const matches=searched?families.filter(f=>f.code===searched&&!f.archived):[];
  return <Card className="mb-4"><SectionHead title="Buscar expediente" sub="Ingrese el número de expediente para cargar sus datos y evitar cruces con otros casos."/><div className="p-5"><SearchBar onChange={setQ} onSearch={v=>{setSearched(v||q);pick(undefined,"RIESGO")}}/>
    {searched&&matches.length===0&&<p className="mt-3 rounded-md bg-warning-soft p-3 text-xs font-bold text-warning">No se encontró el expediente {searched}. Verifique el número (formato 2021-0009).</p>}
    {matches.length>1&&<p className="mt-3 rounded-md bg-warning-soft p-3 text-xs font-bold text-warning">Atención: el número {searched} existe en más de un equipo. Verifique la categoría antes de registrar.</p>}
    {matches.map(f=>{const r=f.recs[0];return <div key={f.fid} className="mt-4 rounded-md border bg-muted/40 p-4 text-xs leading-relaxed">
      <div className="flex flex-wrap items-center gap-2"><b className="text-base text-secondary">{f.code}</b><TeamBadge team={f.team}/><Badge kind="muted">Año {f.year}</Badge><Badge kind={f.stateKind}>{f.state}</Badge><span className="font-bold">{f.label}</span></div>
      <div className="mt-3 grid gap-4 md:grid-cols-2">
        <div><b className="text-[10px] uppercase text-muted-foreground">NNA del expediente ({f.members.length})</b><ul className="mt-1 space-y-1">{f.members.map(m=>{const rec=f.recs.find(r=>r.nna===m.name);return <li key={m.name}><button type="button" disabled={!rec} onClick={()=>pick(rec,f.team)} className={`w-full rounded border px-2 py-1 text-left ${rec&&picked===rec.id?"border-primary bg-accent":"bg-card"} ${rec?"hover:border-primary":"cursor-default"}`}><b className={parseInt(m.age??"")>=18?"text-danger":""}>{m.name}</b>{m.dni&&<span className={parseInt(m.age??"")>=18?"font-bold text-danger":"text-muted-foreground"}> · DNI {m.dni} · {m.birth} ({m.age}){parseInt(m.age??"")>=18?" · 🔴 Cumplió 18 años":""}</span>}{rec&&<small className="ml-1 font-bold text-secondary">{picked===rec.id?"✓ seleccionado":"Usar sus datos"}</small>}</button></li>})}</ul></div>
        {r?<div className="space-y-1"><b className="text-[10px] uppercase text-muted-foreground">Progenitores y responsable</b><p><b>Madre:</b> {r.mother}</p><p><b>Padre:</b> {r.father}</p><p><b>Responsable:</b> {r.responsible}</p></div>:<p className="text-muted-foreground">Expediente de demostración sin datos detallados.</p>}
      </div>
      {r&&<div className="mt-3"><b className="text-[10px] uppercase text-muted-foreground">Objetivo general del PTI</b><p>{r.ptiGeneral}</p></div>}
    </div>})}
  </div></Card>;
}
